{
  "criteria": [
    {
      "id": "C1",
      "level": "Proficient",
      "mark": 4,
      "evidence": [
        {
          "where": "Question 1",
          "quote": "Response measure: the p95 response time is under 1.5 s and no requests are dropped."
        },
        {
          "where": "Question 1",
          "quote": "Response measure: the system should stay up most of the time."
        }
      ],
      "reasoning": "Performance and availability are appropriate choices and are linked to the lunch peak and order abandonment. Both scenarios include the six parts, and the performance measure is measurable. The availability response measure is not measurable, so the scenarios are not fully complete to the Excellent standard."
    },
    {
      "id": "C2",
      "level": "Excellent",
      "mark": 6,
      "evidence": [
        {
          "where": "Question 2",
          "quote": "With five developers, running eight or ten services would mean more time spent on infrastructure than on features."
        },
        {
          "where": "Question 2",
          "quote": "The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."
        }
      ],
      "reasoning": "The modular-monolith recommendation is clear and grounded in team size, the single-VM bottleneck, and deployment downtime. It gives specific trade-offs and acknowledges the reduced independent scaling and shared process-failure risk."
    },
    {
      "id": "C3",
      "level": "Proficient",
      "mark": 5,
      "evidence": [
        {
          "where": "Question 3",
          "quote": "A = 0.9995 × 0.999 × 0.9995 × 0.995 = 0.99301"
        },
        {
          "where": "Question 3",
          "quote": "So the new availability of placing an order is 99.9975%"
        }
      ],
      "reasoning": "Parts (a) and (b) are calculated correctly. In (c), the redundant payment availability is correct, but the other required components are omitted from the end-to-end calculation, making both the stated order-placement availability and downtime incorrect."
    },
    {
      "id": "C4",
      "level": "Excellent",
      "mark": 5,
      "evidence": [
        {
          "where": "Question 4",
          "quote": "When failures exceed a threshold (for example 50% of calls in 10 seconds) the breaker moves to Open and calls fail immediately without waiting"
        },
        {
          "where": "Question 4",
          "quote": "After a wait period the breaker goes Half-Open and lets a few trial calls through."
        }
      ],
      "reasoning": "The circuit breaker mechanism and states are explained correctly and applied to the slow-provider outage. The threshold and time window provide a tuning consideration, and the answer explains how the pattern protects other application functions."
    },
    {
      "id": "C5",
      "level": "Proficient",
      "mark": 3,
      "evidence": [
        {
          "where": "Question 5",
          "quote": "The worst case is that a student sees an item that sold out a minute ago"
        },
        {
          "where": "Question 5",
          "quote": "for payments we choose consistency and availability and give up partition tolerance."
        }
      ],
      "reasoning": "Both choices are reasonable and concrete techniques are named: a cached menu and payment idempotency keys. However, the CAP explanation is incorrect for a network partition: a system cannot choose to give up partition tolerance when the partition occurs; it must trade off consistency versus availability."
    },
    {
      "id": "C6",
      "level": "Proficient",
      "mark": 3,
      "evidence": [
        {
          "where": "Question 6",
          "quote": "Decision: Publish an \"OrderPaid\" event to a durable message queue (RabbitMQ)."
        },
        {
          "where": "Question 6",
          "quote": "Placing an order no longer waits for the outlet, so the response time improves."
        }
      ],
      "reasoning": "Context, Decision, and Consequences are present and specific to CampusEats. The consequences are positive only; a negative consequence such as delayed outlet notification, queue operations, or duplicate deliveries is not stated."
    },
    {
      "id": "C7",
      "level": "Proficient",
      "mark": 3,
      "evidence": [
        {
          "where": "Question 3",
          "quote": "0.018 hours, or about one minute per month."
        },
        {
          "where": "References",
          "quote": "[1] L. Bass, P. Clements, and R. Kazman"
        }
      ],
      "reasoning": "The required headings and order are used, the answers are concise, and citations and a reference list are provided in an IEEE-like style. The reported part (c) availability and downtime do not follow the required two-decimal and one-decimal precision, respectively."
    }
  ],
  "requirements": [
    {
      "id": "R1",
      "met": "partial",
      "where": "Question 1"
    },
    {
      "id": "R2",
      "met": "yes",
      "where": "Question 2"
    },
    {
